<!doctype html><html lang="en"><head><meta charset="utf-8"><title>BOP Test Receipt - {{ $transaction->order_id }}</title><style>body{font-family:Arial,sans-serif;color:#16263c;margin:40px}.receipt{max-width:760px;margin:auto;border:1px solid #ccd7e3;padding:34px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #176b4d;padding-bottom:18px}.test{color:#9a5f00;font-weight:800}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:25px}.item{border-bottom:1px solid #e2e8ef;padding:10px}.item span{display:block;color:#6e7a8a;font-size:12px}.amount{font-size:26px;color:#176b4d}.foot{margin-top:30px;font-size:12px;color:#68778a}@media print{button{display:none}.receipt{border:0}}</style></head><body><main class="receipt"><div class="head"><div><b>LDA SPORTS COMPLEX</b><h1>Payment receipt</h1></div><div class="test">BANK TEST ENVIRONMENT</div></div><div class="grid"><div class="item"><span>Applicant</span><b>{{ $transaction->member->full_name }}</b></div><div class="item"><span>CNIC</span><b>*****-*******-{{ substr(preg_replace('/\D/','',$transaction->member->cnic),-1) }}</b></div><div class="item"><span>Sports complex</span><b>{{ $transaction->challan->sportsComplex->name }}</b></div><div class="item"><span>Challan</span><b>{{ $transaction->challan->challan_no }}</b></div><div class="item"><span>MPGS order</span><b>{{ $transaction->order_id }}</b></div><div class="item"><span>Bank reference</span><b>{{ $transaction->bank_transaction_reference ?: 'Not supplied' }}</b></div><div class="item"><span>Verified at</span><b>{{ optional($transaction->verified_at)->format('d M Y, h:i A') }}</b></div><div class="item"><span>Status</span><b>Verified by MPGS inquiry</b></div></div><p class="amount">PKR {{ number_format((float)$transaction->amount,2) }}</p><p class="foot">This receipt represents a transaction verified in the Bank of Punjab MPGS test environment. It is not evidence of a production bank settlement.</p><button onclick="window.print()">Print receipt</button></main></body></html>
